// Separate row number and seat letter
const match = input.match(/^(\d+)([a-f])$/);
const n = BigInt(match[1]);
const s = match[2];

// Determine which attendant serves the row
// Attendant 1: odd rows, Attendant 2: even rows
const isOddRow = (n % 2n === 1n);

// Time to reach the row (movement + serving previous rows)
let time = 0n;

if (isOddRow) {
    // Attendant 1 serves odd rows: 1,5,9,... (4k+1)
    // Block index (0-based) for odd rows: k = (n-1)/4
    const k = (n - 1n) / 4n;
    // Each block (two rows) takes 12 seconds: 6 (row1) + 1 (move) + 6 (row3) - 1 (no move after)
    // But pattern effectively: 12 seconds per 2 rows
    time = k * 12n;
} else {
    // Attendant 2 serves even rows: 2,4,6,8,... (2k)
    // For even rows, they are grouped in pairs (2,4), (6,8), ...
    // Block index (0-based): k = (n/2 - 1)/2
    const k = ((n / 2n) - 1n) / 2n;
    // Each such block also takes 12 seconds
    time = k * 12n + 6n; // +6 because attendant 2 starts 6 seconds after attendant 1
}

// Within the row: serving order f,e,d,c,b,a
// Right side first: f(1), e(2), d(3); then left: a(4), b(5), c(6)
